const { createShapeId, toRichText } = await import('tldraw')

// Clean the blank page so this illustration is deterministic.
const existing = editor.getCurrentPageShapes()
if (existing.length) editor.deleteShapes(existing.map(s => s.id))

const ids = {}
const made = []
const id = (name) => (ids[name] = createShapeId(`sofpi-${name}`))
const geo = (name, x, y, w, h, label, color='blue', opts={}) => {
  const sid = id(name)
  editor.createShape({
    id: sid, type: 'geo', x, y,
    props: {
      geo: opts.geo || 'rectangle', w, h,
      richText: toRichText(label),
      color,
      fill: opts.fill || 'semi',
      dash: opts.dash || 'draw',
      size: opts.size || 'm',
      font: opts.font || 'draw',
      align: opts.align || 'middle',
      verticalAlign: 'middle',
    },
    meta: { role: opts.role || 'node', package: 'sof-pi' }
  })
  made.push(sid)
  return sid
}
const text = (name, x, y, w, label, color='black', size='m', align='start') => {
  const sid = id(name)
  editor.createShape({ id: sid, type: 'text', x, y, props: {
    richText: toRichText(label), color, size, font: 'draw', textAlign: align, w,
  }, meta: { role: 'annotation', package: 'sof-pi' } })
  made.push(sid)
  return sid
}

// Title and framing copy.
text('title', 90, 45, 1320, 'sof-pi — a personal operating system for AI-assisted work', 'black', 'xl', 'middle')
text('subtitle', 210, 108, 1080, 'Reusable context + capabilities around the pi coding agent', 'grey', 'm', 'middle')

// Center.
geo('core', 585, 315, 310, 190, 'sof-pi\nPERSONAL PI PACKAGE', 'violet', { geo: 'ellipse', fill: 'solid', size: 'l', role: 'core' })
text('core-caption', 620, 515, 240, 'versioned • composable • portable', 'violet', 's', 'middle')

// Four main package pillars.
geo('skills', 110, 205, 300, 110, 'SKILLS\nDomain playbooks + CLI know-how', 'blue', { fill: 'semi', size: 'm', role: 'pillar' })
geo('extensions', 1070, 205, 300, 110, 'EXTENSIONS\nNative tools + slash commands', 'orange', { fill: 'semi', size: 'm', role: 'pillar' })
geo('prompts', 110, 600, 300, 110, 'PROMPTS & THEMES\nReusable instructions + visual identity', 'green', { fill: 'semi', size: 'm', role: 'pillar' })
geo('ecosystem', 1070, 600, 300, 110, 'INSTALLED ECOSYSTEM\nIndependent pi packages', 'yellow', { fill: 'semi', size: 'm', role: 'pillar' })

// Supporting detail cards around each pillar.
geo('skill-workflows', 80, 345, 250, 92, 'WORKFLOWS\nweekly planning • retro', 'blue', { fill: 'none', size: 's', role: 'detail' })
geo('skill-apps', 80, 460, 250, 105, 'APP CONTROL\nNotion • Google • GitHub\nBrowser • WhatsApp', 'blue', { fill: 'none', size: 's', role: 'detail' })
geo('skill-infra', 350, 405, 190, 110, 'DEV & INFRA\nmise • SQL • Stripe\nFly.io • exe.dev', 'blue', { fill: 'none', size: 's', role: 'detail' })

geo('ext-review', 1150, 350, 250, 92, '/review\nPR • branch • commit • folder', 'orange', { fill: 'none', size: 's', role: 'detail' })
geo('ext-search', 1150, 475, 250, 92, 'Perplexity\nsearch tool + /research panel', 'orange', { fill: 'none', size: 's', role: 'detail' })

geo('prompt-files', 145, 745, 230, 92, 'prompts/*.md\nReusable task starters', 'green', { fill: 'none', size: 's', role: 'detail' })
geo('theme-files', 395, 745, 230, 92, 'themes/*.json\nConsistent pi experience', 'green', { fill: 'none', size: 's', role: 'detail' })

geo('openrouter', 855, 745, 235, 92, '@robhowley/pi-openrouter\nmodels • usage • account', 'yellow', { fill: 'none', size: 's', role: 'detail' })
geo('subagents', 1110, 745, 235, 92, 'pi-subagents\ndelegate • parallelize • review', 'yellow', { fill: 'none', size: 's', role: 'detail' })

// Bottom execution flow.
geo('user', 220, 900, 210, 88, 'YOU\nintent + context', 'black', { geo: 'ellipse', fill: 'none', size: 's', role: 'actor' })
geo('agent', 635, 900, 210, 88, 'PI AGENT\nreason + orchestrate', 'violet', { geo: 'ellipse', fill: 'semi', size: 's', role: 'actor' })
geo('outcomes', 1050, 900, 210, 88, 'OUTCOMES\ncode • plans • research • ops', 'black', { geo: 'ellipse', fill: 'none', size: 's', role: 'actor' })
text('flow-label', 500, 865, 480, 'ONE WORKFLOW, MANY CAPABILITIES', 'grey', 's', 'middle')

const connect = (from, to, color='grey', label) => {
  const arrowId = helpers.createArrowBetweenShapes(ids[from], ids[to], {
    color, size: 's', dash: 'draw', bend: 0,
    ...(label ? { text: label } : {})
  })
  return arrowId
}

connect('core', 'skills', 'blue')
connect('core', 'extensions', 'orange')
connect('core', 'prompts', 'green')
connect('core', 'ecosystem', 'yellow')
connect('skills', 'skill-workflows', 'blue')
connect('skills', 'skill-apps', 'blue')
connect('skills', 'skill-infra', 'blue')
connect('extensions', 'ext-review', 'orange')
connect('extensions', 'ext-search', 'orange')
connect('prompts', 'prompt-files', 'green')
connect('prompts', 'theme-files', 'green')
connect('ecosystem', 'openrouter', 'yellow')
connect('ecosystem', 'subagents', 'yellow')
connect('user', 'agent', 'violet')
connect('agent', 'outcomes', 'violet')
connect('core', 'agent', 'violet')

editor.select(...made)
editor.zoomToSelection({ animation: { duration: 0 } })
editor.selectNone()
return { created: made.length, ids, totalShapes: editor.getCurrentPageShapes().length }
JS
